    union {
        int i;
        double d;
    } num;
};

int main(void) {
    struct Value v;

    v.kind = IS_DOUBLE;
    v.num.d = 2.5;
    if (v.kind == IS_INT) {
        printf("整数 %d\n", v.num.i);
